  FT["BN-S-32-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW"] = {"id":"BN-S-32-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"法律部长职能移交","en":"TRANSFER OF THE FUNCTIONS OF THE MINISTER OF LAW","orig":"TRANSFER OF THE FUNCTIONS OF THE MINISTER OF LAW","vi":"Luật chuyển giao chức năng của Bộ trưởng Bộ Tư pháp","th":"พระราชบัญญัติการโอนหน้าที่ของรัฐมนตรีว่าการกระทรวงยุติธรรม","id":"Undang-Undang Pengalihan Fungsi Menteri Hukum","ms":"Akta Pemindahan Fungsi Menteri Undang-Undang"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-32-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-32-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-32-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"BRUNEI DARUSSALAM GOVERNMENT GAZETTE No. S 32\n\nTRANSFER OF THE FUNCTIONS OF THE MINISTER OF LAW It is hereby notified for general information that His Majesty The Sultan and Yang Di-Pertuan has directed that with effect from the 16th. day of September, 1998 all the functions, powers, duties, privileges and benefits of the Minister of Law which have been transferred to or conferred or imposed on him by each of the written laws specified in the first column of the Schedule be transferred to the person specified opposite such written law in the second column of the Schedule.\n\nSCHEDULE Business Names Act {Chapter 92} the Registrar of Business Names Companies Act {Chapter 39} the Registrar of Companies Section 16(3) of the Emergency Chairman of the Public Service (Arbitration) Order, 1994 Commission (S 32/94) Section 48 of the Emergency the Attorney General (Arbitration) Order, 1994 (S 32/94) Inventions Act {Chapter 72} the Registrar of Trade Marks Powers of Attorney Act the Registrar of Powers of {Chapter 13} Attorney Trade Marks Act (Chapter 98} the Registrar of Trade Marks\n\nBY COMMAND\n\nDATO PADUKA HAJI A WANG HAZAIR BIN\n\nHAJI A WANG ABDULLAH Permanent Secretary, Prime Minister's Office, Brunei Darussalam."}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"TRANSFER OF THE FUNCTIONS OF THE MINISTER OF LAW","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F"] = {"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":22,"structureMode":"SECTION","title":{"zh":"儿童与青少年拘留所条例 2010","en":"CHILDREN AND YOUNG PERSONS REMAND HOME REGULATIONS 2010","orig":"CHILDREN AND YOUNG PERSONS REMAND HOME REGULATIONS 2010","vi":"Quy định Trại tạm giam trẻ em và người vị thành niên năm 2010","th":"ข้อบังคับสถานพินิจเด็กและเยาวชน พ.ศ. 2553","id":"Peraturan Rumah Tahanan Anak dan Remaja Tahun 2010","ms":"Peraturan Rumah Tahanan Kanak-Kanak dan Orang Muda 2010"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGULATIONS-2010.pdf》（9 页），本次切分 22 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGULATIONS-2010.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Regulations may be cited as the Children and Young Persons (Remand Home) Regulations, 2010 and shall commence on the same date as the Children and Young Persons Order, 2006. Interpretation."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In these Regulations, unless the context otherwise requires - \"board\", in relation to a remand home, means the board of visitors appointed under section 75(1) in respect of the remand home; \"superintendent\" means the superintendent in charge of a remand home. Responsibilities of superintendent."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"( 1) The superintendent shall be responsible to the Director for the proper management of the remand home under his charge and for the reception and custody of the persons remanded therein.\n\n(2) Subject to the approval of the Director, the superintendent shall determine and draw up\n\n(a) the duties of each member of the staff of the remand home under his charge;\n\n(b) the daily routine for the persons remanded in the remand home under his charge;\n\n(c) fire safety measures and fire drill orders; and\n\n(d) such other matters as the Director may direct to be determined and drawn up. Records to be kept."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"( 1) The superintendent shall cause to be kept the following records {a} a register of admissions to and discharges from the remand home;\n\n(b) a property book in which shall be recorded particulars of any property taken from a remanded person upon or after admission and a brief account of how the property is disposed of upon discharge of that person; {c) a discipline book in which shall be recorded the particulars of every disciplinary action taken against any remanded person; {d) a daily register of the presence or absence of each person remanded therein;\n\n(e) a log book in which shall be entered every event of importance connected with the management of the remand home; {f) a board of visitors book in which the names of the members of the board shall be entered and in which they may make comments concerning the remand home; and {g) such other records as the Director may direct to be kept.\n\n(2) The records kept under sub-regulation (1) shall be(a) available at any time for inspection by any member of the board; and {b) placed before the board at any meeting thereof if the board so requires. Superintendent to report death, injury or admission to hospital of remanded person."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A5","no":5,"noLabel":{"en":"Section 5."},"heading":{"en":"Superintendent to report death, injury or admission to hospital of remanded"},"text":{"en":"( 1) Where a remanded person dies or is seriously injured, the superintendent shall, as soon as possible, report the death or serious injury to the police, the Director, the board and the parent or guardian of the remanded person.\n\n(2) Where it becomes necessary for a remanded person to be admitted to a hospital for medical treatment, the superintendent shall, as soon as possible, inform the Director and the parent or guardian of the remanded person.\n\n(3) The superintendent shall ensure that no surgical treatment is carried out on a remanded person without the prior consent of his parent or guardian, unless the medical officer certifies in writing that the delay necessary in obtaining such consent would cause the remanded person unnecessary suffering or endanger his health. Personal effects of remanded person."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"(1) The personal effects of a remanded person shall, upon his admission to a remand home, be taken from him by the superintendent, and, subject to subregulation (2), such personal effects shall be returned to him only upon his discharge from the remand home.\n\n(2) Where any item among the personal effects of a remanded person at the time of his admission is of a perishable or dangerous nature, the superintendent shall cause the item to be destroyed.\n\n(3) The superintendent shall cause the particulars of all personal effects taken from the remanded person upon his admission to be recorded in the property book. Medical examination."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Every remanded person shall upon his admission to a remand home be examined by a medical officer. Provision of bed, clothing and other articles."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Each remanded person shall be provided with a separate bed, his own set of clothing and such other personal articles as may be necessary for his stay in the remand home. Food."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Every remanded person shall be supplied with food that is prepared on the recommendation of a dietician and approved by the Director. Instruction and facilities for religious observance."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Instruction and facilities for religious observance shall be provided for all Muslim children. Continuing education."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A remanded person shall be accorded facilities, so far as is practicable, to continue with his education. Daily chores."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"A remanded person may be required to perform daily chores which may include making beds, cleaning dormitories or similar work in or about the buildings or grounds of the remand home. Recreation."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Recreation and exercise shall be provided daily for remanded persons. Writing and receipt of letters."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"(1) Subject to sub-regulation (2), a remanded person may send and receive letters.\n\n(2) No letter shall be sent or received by a remanded person unless its contents have been screened by the superintendent or an officer authorised by him. Visits."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"A remanded person shall be allowed to receive visitors at such reasonable intervals as the superintendent may determine. Serious illness."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Where, in the opinion of the superintendent or of any medical officer, it is necessary to refer a remanded person to a hospital, the superintendent shall arrange to refer the remanded person to the hospitaL Remanded persons to obey lawful orders."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Every remanded person shall obey the lawful orders of the staff. Fair discipline."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Every member of the staff in a remand home shall treat every remanded person justly and firmly in the enforcement of discipline. Superintendent's orders."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"The superintendent shall issue orders for the purpose of managing the remand home. Punishment for indiscipline."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"\\1) Where the imposition of punishment on any remanded person is necessary for the maintenance of discipline, the superintendent may impose any one or more of the following forms of punishment (a} forfeiture of recreation for a specified period not exceeding 3 days;\n\n(b) performance of extra duties in and around the buildings or compound of the remand home; and\n\n(c) subject to regulation 21, corporal punishment. \\2) The superintendent shall record in the discipline book the reasons for his decision to impose punishment on any remanded person and the form of punishment imposed. Corporal punishment."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"(1) The superintendent and staff of the remand home shall make every effort to enforce discipline without resort to corporal punishment.\n\n(2) No corporal punishment shall be imposed on a remanded person unless the superintendent is satisfied after an inquiry that the remanded person is guilty of serious misconduct and the misconduct is of such a nature as to warrant the imposition of corporal punishment.\n\n(3) The superintendent shall record in the discipline book the particulars and evidence of the remanded person's alleged misconduct, his finding on the evidence, and the grounds of his decision to impose corporal punishment on the remanded person.\n\n(4) Corporal punishment shall be administered only on the following conditions - (a} where corporal punishment is to be administered to a male remanded person\n\n(i) it shall be administered by the superintendent or an officer authorised by him;\n\n(ii) it shall be inflicted with a light rattan;\n\n(iii) the number of strokes inflicted shall not exceed 8;\n\n(iv) the strokes may be inflicted on the remanded person's palm or on his buttocks over his ordinary cloth shorts; and\n\n(v) it shall not be administered in the presence of any other remanded person; and\n\n(b) where corporal punishment is to be administered to a female remanded person -\n\n(i) it shall be administered by the superintendent or a female officer authorised by the superintendent;\n\n(ii) it shall be inflicted with a light rattan;\n\n(iii) the number of strokes inflicted shall not exceed 8;\n\n(iv) the strokes shall be inflicted on the remanded person's palm only; and\n\n(v) it shall not be administered in the presence of any other remanded person.\n\n(5) Corporal punishment shall not be administered to any remanded person who suffers from any physical or mental disability.\n\n(6) In any case in which corporal punishment is administered, the superintendent shall -\n\n(a) record in the discipline book, immediately thereafter, such details of the corporal punishment as may be required by the Director; and\n\n(b) as soon as possible thereafter report the facts and circumstances of the case to the Director. Prohibition of unauthorised forms of corporal punishment."}},{"id":"BN-S-32-2010-CHILDREN-AND-YOUNG-PERSONS-REMAND-HOME-REGU-C8AF6F-A22","no":22,"noLabel":{"en":"Section 22."},"heading":{"en":"CHILDREN AND YOUNG PERSONS ORDER, 2006"},"text":{"en":"(1) Except as provided under regulation 21, no member of the staff of a remand home shall subject any remanded person to any other form of corporal punishment. 12) For the purpose of sub-regulation (1), \"any other form of corporal punishment\" includes striking, cuffing, shaking or punching a resident, or subjecting him to any other form of physical violence. Made this 11th. day of Rabiulawal, 1431 Hijriah corresponding to the 25th. day of February, 2010.\n\nPEHIN ORANG KAYA SETIA PAHLAWAN DATO SERI SETIA DR. A WANG HAJI AHMAD BIN HAJI JUMAT Minister of Culture, Youth and Sports, Brunei Darussalam."}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CHILDREN AND YOUNG PERSONS REMAND HOME REGULATIONS 2010","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-32-2017-E-PATENTS-AMENDMENT-ORDER-2017"] = {"id":"BN-S-32-2017-E-PATENTS-AMENDMENT-ORDER-2017","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":3,"structureMode":"SECTION","title":{"zh":"专利修正命令 2017","en":"PATENTS AMENDMENT ORDER 2017","orig":"PATENTS AMENDMENT ORDER 2017","vi":"Sắc lệnh sửa đổi Sắc lệnh Sáng chế năm 2017","th":"คำสั่งแก้ไขเพิ่มเติมคำสั่งสิทธิบัตร พ.ศ. 2560","id":"Perintah Perubahan Perintah Paten Tahun 2017","ms":"Perintah Pindaan Perintah Paten 2017"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-32-2017-E-PATENTS-AMENDMENT-ORDER-2017.pdf》（3 页），本次切分 3 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-32-2017-E-PATENTS-AMENDMENT-ORDER-2017.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-32-2017-E-PATENTS-AMENDMENT-ORDER-2017-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Citation"},"text":{"en":"This Order may be cited as the Patents (Amendment) Order, 2017. of section 36 of S 5712011"}},{"id":"BN-S-32-2017-E-PATENTS-AMENDMENT-ORDER-2017-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"Amendment of section 36 of S 571201 1"},"text":{"en":"Section 36 of the Patents Order, 2011, in this Order referred to as the principal Order, is amended - (a/ in subsection (2) -\n\n(i) (a], by deleting \"4\" from the last line and by \"5\" therefor;\n\n(ii) by deleting \"2\" from the last line and by substituting \"3\" therefor;\n\n(b) in subsection (3) [i) (a], by deleting \"4\" from the last line and by \"5\" therefor;\n\n(ii) in paragraph (b/, by deleting \"2\" from the last line and by \"3\" therefor; (iii] in paragraph (cl -\n\n(A) in sub-paragraph (it, by deleting \"4\" and by substituting \"5\"\n\n(B) in sub-paragraph (ii), by deleting \"2\" and by substituting \"3\" (cl in subsection 5(b/, by deleting \"2\" from the last line and by substituting \"3\" therefor; (dl in subsection 6(b/, by deleting \"2\" from the last line and by substituting \"3\" therefor. Amendment of section 77"}},{"id":"BN-S-32-2017-E-PATENTS-AMENDMENT-ORDER-2017-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"BRUNEI DARUSSALAM GOVERNMENT GAZETTE"},"text":{"en":"Section 77 of the principal Order is amended, in subsection l(fl(ii), by inserting \"or inequitable conduct\" immediately after \"misrepresentation\" Made this 13th. day of Rejab, 1438 Hijriah corresponding to the 10th. day of April, 2017 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM"}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"PATENTS AMENDMENT ORDER 2017","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-33-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW-1"] = {"id":"BN-S-33-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW-1","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"法律部长职能移交","en":"TRANSFER OF THE FUNCTIONS OF THE MINISTER OF LAW 1","orig":"TRANSFER OF THE FUNCTIONS OF THE MINISTER OF LAW 1","vi":"Luật chuyển giao chức năng của Bộ trưởng Bộ Tư pháp","th":"พระราชบัญญัติการโอนหน้าที่ของรัฐมนตรีว่าการกระทรวงยุติธรรม","id":"Undang-Undang Pengalihan Fungsi Menteri Hukum","ms":"Akta Pemindahan Fungsi Menteri Undang-Undang"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-33-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW-1.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-33-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW-1.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-33-1998-TRANSFER-OF-THE-FUNCTIONS-OF-THE-MINISTER-OF-LAW-1-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"28th. SEPTEMBER, 1998 No. S 33\n\nTRANSFER OF THE FUNCTIONS OF THE MINISTER OF LAW It is hereby notified for general information that His Majesty The Sultan and Yang Di-Pertuan has directed that with effect from the 16th. day of September, 1998 all the functions, powers, duties, privileges and benefits of the Minister of Law which have been transferred to or conferred or imposed on him by the Criminal Law (Preventive Detention) Act (Chapter 150} are hereby transferred to the Minister of Home Affairs.\n\nBY COMMAND\n\nDATO PADUKA HAJI A WANG HAZAIR BIN\n\nHAJI A WANG ABDULLAH Permanent Secretary, Prime Minister's Office, Brunei Darussalam."}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"TRANSFER OF THE FUNCTIONS OF THE MINISTER OF LAW 1","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-33-2000-DESCRIPTION-OF-CURRENCY-NOTE-500-1"] = {"id":"BN-S-33-2000-DESCRIPTION-OF-CURRENCY-NOTE-500-1","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"SECTION","title":{"zh":"500 元纸币说明","en":"DESCRIPTION OF CURRENCY NOTE 500 1","orig":"DESCRIPTION OF CURRENCY NOTE 500 1","vi":"Sắc lệnh Mô tả tiền giấy mệnh giá 500","th":"คำสั่งลักษณะธนบัตรชนิดราคา 500","id":"Perintah Ciri-Ciri Uang Kertas Pecahan 500","ms":"Perintah Keterangan Wang Kertas Nilai 500"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-33-2000-DESCRIPTION-OF-CURRENCY-NOTE-500-1.pdf》（2 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-33-2000-DESCRIPTION-OF-CURRENCY-NOTE-500-1.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-33-2000-DESCRIPTION-OF-CURRENCY-NOTE-500-1-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"':1:1 e; 0~ )l \"' s::: Ill ~~ ~ ? Ill -"}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"DESCRIPTION OF CURRENCY NOTE 500 1","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9"] = {"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":65,"structureMode":"SECTION","title":{"zh":"儿童与青少年安全场所条例 2010","en":"CHILDREN AND YOUNG PERSONS PLACE OF SAFETY REGULATIONS 2010","orig":"CHILDREN AND YOUNG PERSONS PLACE OF SAFETY REGULATIONS 2010","vi":"Quy định Nơi tạm trú an toàn cho trẻ em và người vị thành niên năm 2010","th":"ข้อบังคับสถานที่ปลอดภัยสำหรับเด็กและเยาวชน พ.ศ. 2553","id":"Peraturan Tempat Aman bagi Anak dan Remaja Tahun 2010","ms":"Peraturan Tempat Selamat bagi Kanak-Kanak dan Orang Muda 2010"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-REGULATIONS-2010.pdf》（23 页），本次切分 65 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-REGULATIONS-2010.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Regulations may be cited as the Children and Young Persons (Places of Safety) Regulations, 2010 and shall commence on the same date as the Children and Young Persons Order, 2006. Interpretation."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In these Regulations, unless the context otherwise requires - \"Board\" means a Board of Visitors appointed under regulations made under section 102; \"code of conduct\" means the code of conduct referred to in regulation 4; \"medical officer\" means the medical officer appointed for a place of safety under regulation 20; \"Panel\" means the Panel of Reviews and Discharges referred to in regulation 63(1); \"resident\" means any child who has been admitted to a place of safety; \"staff\" means any person working in a place of safety, and includes the Warden and a deputy Warden; \"Superintendent\", in relation to a place of safety, means the Superintendent appointed under regulation 3(2) and who is exercising jurisdiction over that place of safety; \"Warden\", in relation to a place of safety, means the Warden appointed under regulation 3(2) and who is exercising jurisdiction over that place of safety. Administration."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"( 1) A place of safety shall be under the general charge and administration of a Warden, who shall be subject to and shall comply with such directions as may be given by the Superintendent.\n\n(2) The Minister, with the approval of His Majesty the Sultan and Yang Di-Pertuan, shall appoint for each place of safety, a Superintendent, a Warden and such number of other staff as he may consider necessary. Code of conduct."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Superintendent shall prepare a code of conduct in relation to the proper management of a place of safety to be complied with by every person to whom it applies.\n\nRESPONSIBILITIES OF DIRECTOR Director to ensure Regulations are obeyed."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"PART II"},"text":{"en":"(1) The Director shall ensure that each place of safety is administered in accordance with these Regulations and any other regulations made under the Order.\n\n(2) For that purpose he or his representative shall regularly visit and inspect each place of safety and give consideration to all matters brought to his notice, the comments given and the recommendations made, by the Board. Delegation of powers and duties of Director."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"PART II"},"text":{"en":"The Director may delegate in writing the exercise or performance of any of the powers or duties conferred or imposed on him by these Regulations to any Community Development Officer. Determining duties of Superintendent, Warden and staff."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"PART II"},"text":{"en":"The Director may determine the duties of the Superintendent, Warden and staff, other than the duties expressly imposed by these Regulations, to be carried out in the best interests of the residents. Supply of copies of Regulations to members of Board and staff."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"PART II"},"text":{"en":"The Director shall ensure that a copy of these Regulations is supplied to every member of a Board on his appointment, and to the Superintendent, Warden and to all staff. Number of residents."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"PART II"},"text":{"en":"The Director shall determine the number of residents to be accommodated in a place of safety at any time, and such number shall not be exceeded without his prior approval.\n\nRESPONSIBILITIES OF SUPERINTENDENT AND WARDEN Responsibility of Superintendent to Director."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"PART III"},"text":{"en":"The Superintendent shall be responsible to the Director for - {a} ensuring that the place of safety is operated and managed satisfactorily and that the welfare of the residents in the place of safety is promoted in a proper manner; {b} the efficient conduct, management and discipline of the place of safety; and {c} all the property and the services provided at the place of safety and for taking such measures as may be necessary to maintain them in proper order. Duties of Warden."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"PART III"},"text":{"en":"In addition to the duties determined by the Director under regulation 7, the duties of the Warden shall include - {a} making daily inspections of the parts in the place of safety where the residents are accommodated or given training; {b) making visits to residents confined to sick bay, in hospital or otherwise segregated; {c) making rounds of the place of safety during the night, at varying times and at least 3 times a week to satisfy himself as to the state of the place of safety; {d) ensuring the maintenance of the records required to be kept and maintained under Part VII; {e) reporting immediately the death or serious illness of, or any serious injury or infectious disease suffered by, any resident to his parent, guardian or nearest relative, and to the Director, Superintendent and chairman of the Board; ({) notifying immediately the police of any violent or sudden death of a resident, and sending without delay to the Director a written report of any enquiry relating thereto. Attention to welfare of residents."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"PART III"},"text":{"en":"( 1) The Warden shall exercise close and constant supervision over the place of safety by {a) giving special attention to the health, welfare, education, training and development of the residents; {b) providing facilities and opportunities to enable the residents to develop physically, mentally, spiritually and socially in a clean and healthy environment.\n\n(2) The attention to be given to the welfare of the residents includes{a) interviewing every resident immediately after admission and immediately prior to his discharge from the place of safety; {b) providing guidance, love and affection as well as developing a positive and healthy relationship between staff and the residents; {c) providing counselling for the residents; and {d) so far as practicable, carrying into effect any written recommendation made by the medical officer for the alteration of the discipline or treatment of any residents. Determining duties of staff."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"PART III"},"text":{"en":"The Warden shall determine the daily duties of the staff and ensure that - (a} all staff undergo a medical examination annually; and fbJ staff supervise the daily activities of the residents. Monthly report."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"PART III"},"text":{"en":"(1) The Warden shall prepare and keep a monthly report which shall include the comments given by members of the Board and details of admissions, discharges and abscondances, and shall place the report before the Board at its next meeting.\n\n(2) A copy of the report shall be sent to the Director and Superintendent. Delegation of powers and duties of Warden."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"PART III"},"text":{"en":"(1) During any absence of the Warden from the place of safety, any power conferred or duty imposed on him by these Regulations may be exercised or performed by the deputy Warden or, in his absence, by a senior and experienced member of staff appointed by the Warden to discharge his functions.\n\n(2) The Warden may, at any time, with the approval of the Director, delegate to any senior and experienced member of staff the performance of any of his duties under these Regulations. Absence of Warden from place of safety."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"PART III"},"text":{"en":"(1) The Warden shall obtain the approval of the Superintendent and notify the chairman of the Board if he wishes to leave the place of safety for more than 24 hours, and shall ensure that arrangements satisfactory to the Superintendent are made for the conduct of the place of safety during his absence.\n\n(2) The Warden shall require the approval of the Director for any absence of more than 4 weeks. Fire precautions."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"PART III"},"text":{"en":"(1) The Warden shall draw up fire precaution rules and fire drill procedures as approved by the Director of Fire and Rescue and shall ensure that appliances for the extinction of fires are at all times kept in order and ready for use.\n\n(2) The Warden shall ensure that all staff and, as far as practicable, the residents are conversant with fire procedures.\n\n(3) Fire drills shall be held at least twice a year.\n\n(4) The Warden shall keep a written record of all fire drills. Compliance with directions from Director."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"PART III"},"text":{"en":"The Warden shall comply with all directions issued by the Director relating to the performance of his duties and the management of the place of safety.\n\nMEDICAL FACILITIES Provision of medical and dental facilities."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"PART IV"},"text":{"en":"The Director shall make arrangements for - {a} the provision of medical and dental care for the residents in a place of safety; {b) a sick bay and a medical room to be provided in each place of safety. Appointment of medical officer."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"PART IV"},"text":{"en":"The Director-General of Medical Services shall appoint a medical officer for each place of safety. Duties of medical officer."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"PART IV"},"text":{"en":"The medical officer shall {a) carry out a thorough medical examination of each resident on admission, thereafter annually, and again shortly before the resident leaves the place of safety; {b) carry out a weekly inspection on the hygienic condition of the place of safety; {c) carry out the examination and treatment of residents and staff entitled to medical treatment; {d} keep medical records in a form and manner approved by the Director-General of Medical Services; and\n\n(e) furnish such reports and certificates as the Director may require. Medical treatment of residents."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"PART IV"},"text":{"en":"(1) Notwithstanding the other provisions of this regulation, the medical officer shall, if practicable, visit the place of safety daily at such times as the Director-General of Medical Services may determine.\n\n(2) The medical officer shall attend to a sick resident as soon as he receives a complaint and shall report the matter and any recommendation on further medical treatment to the Superintendent immediately thereafter.\n\n(3) The medical officer shall regularly visit a resident who is confined to a room or to whom his special attention is directed.\n\n(4) Where in the opinion of the medical officer a resident requires treatment in a hospital, the Superintendent shall make arrangements for the resident to be received in a hospital for such period as may be necessary.\n\n(5) During the period of such stay in the hospital, the resident shall be deemed to be in the custody of the Superintendent.\n\n(6) Where a surgical operation for a resident is considered necessary and urgent, and the consent of the parent or guardian as required by the hospital authorities is not obtainable within the time available, the Superintendent shall sign the consent for and on behalf of the parent or guardian. Reports on dangers to residents' health."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"PART IV"},"text":{"en":"Whenever the medical officer has reason to believe that the health of a resident is likely to be injuriously affected by the discipline or treatment in a place of safety, he shall immediately report the matter in writing to the Superintendent together with his recommendations. Contagious diseases."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"PART IV"},"text":{"en":"The medical officer shall forward to the Superintendent in writing a recommendation to separate from other residents, any resident suffering or suspected of suffering, from any infectious or contagious disease, and shall immediately take steps to treat such disease. First aid box."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"PART IV"},"text":{"en":"There shall be in every place of safety at least one first aid box which shall be kept fully equipped.\n\nPARTV\n\nRESPONSIBILITIES OF STAFF Compliance with code of conduct."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"PART IV"},"text":{"en":"Every staff shall comply with the code of conduct of the place of safety and shall assist the Superintendent in the administration thereof. Compliance with instructions and orders of Superintendent."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"PART IV"},"text":{"en":"Every staff shall obey all lawful instructions and orders of the Superintendent. Responsibility of staff."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"PART IV"},"text":{"en":"(1) Staff shall be responsible to the Warden, Superintendent and Director in ensuring that the health and welfare of the residents in the place of safety is promoted in a proper manner.\n\n(2) Staff shall report to the Superintendent and Warden any abuse or impropriety of which he is aware. Leaving place of safety."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"PART IV"},"text":{"en":"No staff shall leave the place of safety while on duty without the prior permission of the Superintendent. Loans and gifts."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"PART IV"},"text":{"en":"No staff shall borrow or lend any money or valuables from or to any resident, or accept any gift from any resident or any visitor of a resident. Disciplinary action."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"PART IV"},"text":{"en":"Any staff who neglects his responsibilities or fails in his duties with regard to these Regulations shall be liable to disciplinary action. Health of resident to be brought to notice of Warden."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"PART IV"},"text":{"en":"il) Staff shall observe the daily health of each resident with regard to appearance, general cleanliness, personal hygiene, temperature, skin troubles and any other abnormal conditions. {2) Staff shall direct the attention of the Warden to any resident, whether he complains or not, who appears to be unwell or whose state of mind appears to require special care.\n\n(3) The Warden shall without delay bring any such case to the notice of the medical officer. Staff dealing with residents."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"PART IV"},"text":{"en":"(1) Staff, when dealing with a resident, shall only use such reasonable force as is necessary. {2) Staff shall not deliberately act in a manner calculated to provoke a resident. [3) Staff shall not discuss his duties or any matter of discipline or arrangement in a place of safety within the hearing of a resident. {4) Staff shall not deal with a resident for any improper purpose. Staff not to communicate with media."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"PART IV"},"text":{"en":"(1) Staff shall not make any communication to any representative of the media, without the authority of the Superintendent, on any matter which has come to his know ledge in the course of his duties.\n\n(2) Staff shall not, without the authority of the Superintendent, publish any matter or make any public pronouncement relating to a place of safety or to any resident.\n\nDUTIES AND PRIVILEGES OF RESIDENTS Compliance with code of conduct and lawful orders."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"PART VI"},"text":{"en":"Every resident shall comply with the code of conduct of the place of safety and shall obey all the lawful instructions and orders of the Superintendent, Warden and staff. Submission to treatment."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"PART VI"},"text":{"en":"Every resident shall submit to all medical and other treatment for his health and welfare, as the medical officer considers necessary. Leaving place of safety."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"PART VI"},"text":{"en":"A resident shall not leave the place of safety without the prior permission of the Warden, or (as the case may be) the deputy Warden or a senior staff authorised by the Warden for that purpose. Acts of violence."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"PART VI"},"text":{"en":"A resident shall not resort to any form of violence. Earnings."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"PART VI"},"text":{"en":"A resident shall be allowed to retain any earnings derived from any approved employment for training purposes in a savings account opened for him by the Warden, subject to such conditions as may be imposed by the Director. Recreation."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"PART VI"},"text":{"en":"Adequate facilities and equipment shall be provided by the Warden for free time and recreational activities, including organised games, social activities, excursions and visits outside the place of safety under the supervision of staff. Home leave."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"PART VI"},"text":{"en":"(1) The Director shall grant leave of absence to a resident to enable him to visit his parents and relatives or, if in his opinion the grant of such leave is impracticable or undesirable, arrangements may be made by the Superintendent for the resident to utilise his period of leave with a suitable foster-family as the Director may approve.\n\n(2) The resident shall be examined by a medical officer as soon as practicable after the resident's return to the place of safety. Correspondence."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"PART VI"},"text":{"en":"(1) Every resident shall be encouraged to meet his parents, guardians or near relatives at least once a month.\n\n(2) Every resident shall be allowed to receive letters from his parents, guardians, relatives and friends unless circumstances make it impracticable or undesirable.\n\n(3) The Warden may open and examine any letter or parcel sent or received by a resident. Visits."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"PART VI"},"text":{"en":"Every resident shall be allowed to receive visits from his parents, guardians and relatives unless circumstances make such visits impracticable or undesirable. Suspension of privileges."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"PART VI"},"text":{"en":"( 1 J The Warden may suspend any privilege conferred on a resident by these Regulations if he is satisfied that it interferes or is likely to interfere with the discipline of the place of safety.\n\n(2) Any suspension of privileges under sub-regulation Ill shall be recorded in the resident's personal case file and in a register kept for that purpose.\n\nRECORDS TO BE KEPT AND MAINTAINED Records."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"PART VII"},"text":{"en":"The records required to be kept and maintained under these Regulations are{a} a register of admissions and discharges, including{i) the name and home address of each resident admitted, or the home address of at least one parent or guardian of each resident admitted; and {ii) the address at which or the means by which the parent, guardian or nearest relative of the resident admitted may be informed in cases of illness or other emergency while the resident is in the place of safety; {b) a medical record in which shall be recorded particulars of changes in the growth and development of each resident including particulars of immunisation, illnesses or accidents occurring and 1 action taken in respect thereof; {c) a daily register of the presence or absence of each resident; {d) a case file of each resident in which shall be kept all relevant documents including his case history; {e) a property book for the residents wherein shall be recorded every possession brought into the place of safety by a resident, a description of the item, its approximate monetary value and the method of disposal thereof on the discharge of the resident; {f) a log book in which shall be entered every event of importance connected with the place of safety; {g) a book to record comments given by a member of the Board; {h) a register of all gifts presented by the public to the place of safety; {i) a punishment book; {j) an inventory of all property in the place of safety; {k) such other records as may be directed by the Director.\n\nADMISSION Admission."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"PART VIII"},"text":{"en":"No resident shall be admitted to or discharged from a place of safety except in accordance with the provisions of any written law or as otherwise approved by the Director. Custody of property of resident."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"PART VIII"},"text":{"en":"(1) All monies, documents, jewellery, clothing and other personal effects belonging to a resident which are not allowed to be retained by him shall be placed in the custody of the Warden who shall keep an inventory of belongings in the property book kept under regulation 45{e).\n\n(2) Every inventory shall be signed or authenticated by the resident and the Warden and witnessed by a member of the staff.\n\n(3) All items placed in the custody of the Warden under sub-regulation !1) shall be returned to the resident on his discharge from the place of safety. Acquainting resident with duties and privileges."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"PART VIII"},"text":{"en":"(1) Upon the admission of a resident into the place of safety, the Warden shall as far as practicable acquaint the resident with the objectives of the place of safety, his duties and privileges and shall assign him to a dormitory. {2) Upon a resident being assigned to a dormitory, the member of the staff who is the officer-in-charge of that dormitory shall help the resident to settle down.\n\nCARE OF RESIDENTS Furniture, equipment and clothing provided for residents."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"PART IX"},"text":{"en":"[1) Every resident shall be provided with {a} a separate cot or bed; {b) adequate toilet facilities; {c) suitable clothing and such other personal effects as approved by the Director.\n\n(2) A sufficient quantity of toys or equipment for play activities considered suitable by the Director shall be provided in a place of safety.\n\n(3) Cots, beds and bedding shall be washable and of suitable types and designs and shall be maintained in a clean condition.\n\n(4) The bedding of each resident shall be kept under hygienic conditions. Safety and cleanliness of premises etc."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"PART IX"},"text":{"en":"{ 1) The premises, furniture, furnishings, fittings and equipment in a place of safety, and the toys and materials to which the residents have access therein, shall be maintained in a safe, clean and serviceable condition.\n\n(2) Any hazard to the safety of the residents in a place of safety shall, so far as is reasonably practicable, be removed or made inaccessible to the residents. {3) Smoking or spitting in a place of safety is forbidden. Diet."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"PART IX"},"text":{"en":"( 1) Each resident shall be provided with sufficient and varied food based on a dietary scale recommended by a dietician and approved by the Director.\n\n(2) The dietary scale shall include a menu appropriate to the age and health of each resident.\n\n(3) Proper arrangements shall be made for the preparation, cooking and serving of food as required by religion or custom.\n\n(4) A copy of the dietary scale and menu shall be posted in the kitchen, in the dining hall and in the office of the place of safety. Instruction and facilities for religious observance."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"PART IX"},"text":{"en":"Instruction and facilities for religious observance shall be provided for all Muslim residents. Providing living skills, educational and vocational training and employment."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"PART IX"},"text":{"en":"(1) A social treatment plan shall be drawn up by the Superintendent for each resident and no resident shall be allowed to engage in any activity that does not form part of this plan, which shall be drawn up to include opportunities for the resident's physical, mental, socio-emotional and language development.\n\n(2) A programme catering to the specific needs of each individual preschool resident shall be planned to promote total development.\n\n(3) Residents who have attained school-going age shall attend a recognised school outside the place of safety, unless there are circumstances which make it impossible or impractical for them to do so.\n\n(4) Educational and vocational training of the residents shall, so far as practicable, be directed towards their preparation for proficiency in a particular type of skill or employment, taking into consideration the capacity and preference of each resident and the type of employment likely to be available for his future. Wherever practicable, the parent or guardian shall be consulted.\n\n(5) The Superintendent shall be responsible for seeing that the usual progress reports are received for each resident who attends school or undergoes vocational training and that these reports are placed in the resident's case file.\n\n(6) Educational and vocational training programmes shall be approved by the Director and may include such training outside the place of safety as circumstances permit.\n\n(7) The employment of a resident shall require the approval of the Director and no resident shall be employed in such a way as to impair his capacity for profiting by instruction or to deprive him of reasonable recreation and leisure, and his employment shall be in accordance with any written law relating to the employment of children. (8} A personal record of terms, hours, place and nature of work shall be kept for each resident who is receiving employment or training in employment outside the place of safety. The Superintendent may cause these records to be made available for inspection by the resident's parents or guardians or by such other persons as he may approve. Involvement of parents or guardians."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"PART IX"},"text":{"en":"The Superintendent of a place of safety shall as far as possible keep constantly in touch with the parents or guardians of every resident to ensure their understanding and co·operation with regard to the welfare, health, education or training, behaviour and progress of their resident.\n\nDAILY TIMETABLE OF ACTIVITIES Daily timetable."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"PART X"},"text":{"en":"(1} The daily timetable of a place of safety, including the hours of rising and retiring, educational and vocational training, domestic work, meals, leisure and recreation, indoor and outdoor activities, shall be approved by the Director.\n\n(2) A copy of the daily timetable shall be posted on the main notice·board, in the dining hall and in the office of the place of safety.\n\n(3) Any substantial deviation from the daily timetable shall be entered in the log book and a written notification thereof shall be sent forthwith by the Warden to the Superintendent. Daily activities."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"PART X"},"text":{"en":"The programme of daily activities of a place of safety, including outdoor activities organised by the place of safety, shall - {a) be supervised by a member of the staff; {b) be appropriate to the ages and abilities of the residents concerned and provide opportunities for their development; and\n\n(c) include opportunities for periods of indoor and outdoor activities and periods of undisturbed rest.\n\nUNAUTHORISED ABSENCE OR ESCAPE Reporting of unauthorised absence or escape."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"PART XI"},"text":{"en":"(1) The Superintendent shall, within 24 hours of its discovery, report any unauthorised absence or escape of any resident from the place of safety to the police, Director, Community Development Officer of the area in which the resident lives, parent, guardian or nearest relative, and chairman of the Board.\n\n(2) If any resident runs away or escapes from his home during holidays or home leave, the parents or guardians shall immediately make a report to the Superintendent and the police.\n\nDISCIPLINE AND PUNISHMENT Discipline."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"PART XII"},"text":{"en":"The discipline of residents in a place of safety shall be based on moral guidance and shall be promoted by a system of rewards and privileges. Punishment which may be inflicted."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"PART XII"},"text":{"en":"Where punishment is necessary for the maintenance of discipline, it shall consist of forfeiture of rewards and privileges, or suspension from games or recreational activities. Punishment book."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"PART XII"},"text":{"en":"( 1) The Warden shall be responsible for the immediate recording of any punishment in the punishment book kept under regulation 45(i} and shall enter therein such particulars as may be required by the Director.\n\n(2) The punishment book shall be examined by the Board at each meeting and shall be signed by the chairman of the Board or the member presiding at that meeting.\n\n(3) The punishment book shall be available for inspection at all times by the Director or his representative. No resident to punish another resident."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"PART XII"},"text":{"en":"No resident shall be allowed to administer any form of punishment to any other resident. Corporal or humiliating punishment prohibited."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"PART XII"},"text":{"en":"(1) No corporal punishment shall be administered by any member of the staff.\n\n(2) Any member of the staff committing a breach of sub-regulation {1) shall be liable to disciplinary action.\n\n(3) In sub-regulation (1), \"corporal punishment\" includes striking, punching, slapping, cuffing, shaking or any other form of physical violence.\n\nREVIEWS AND DISCHARGES Panel of Reviews and Discharges."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"PART XIII"},"text":{"en":"[ 1) The Panel of Reviews and Discharges shall consist of the Superintendent or his representative, the Warden and the member of the staff in charge of the resident concerned. {2) The Panel shall meet at least three times a year.\n\n(3) The Warden shall prepare a progress report on each resident at least once every 3 months for review by the Panel.\n\n(4) At each review the Panel shall consider the date on which the resident will be fit to be discharged, and the recommendations of the Panel with regard to the discharge of the resident shall be forwarded to the Director for his approval. The Director shall consult the Panel prior to giving his approval under this subregulation.\n\n(5) In the case where a resident is to be discharged into the care of a foster family, the Community Development Officer concerned shall conduct a study on the suitability of the family and the home concerned with a view to receiving the resident.\n\n(6) The Panel shall maintain a review and discharge register showing the date and result of its review of each case and the reasons for its decision. Aftercare."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"PART XIII"},"text":{"en":"When the discharge of a resident has been duly authorised, either by the Panel or through the order of a court, the Superintendent shall make arrangements for the discharge and aftercare of the resident after consulting the Community Development Officer or any person responsible for his aftercare, who shall be given all relevant information and assistance necessary for the aftercare of the resident.\n\nGENERAL Exemption."}},{"id":"BN-S-33-2010-CHILDREN-AND-YOUNG-PERSONS-PLACE-OF-SAFETY-291CB9-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"PART XIV"},"heading":{"en":"CHILDREN AND YOUNG PERSONS ORDER, 2006"},"text":{"en":"The Minister may, upon the recommendation of the Director and by notification published in the Gazette, exempt any place of safety from all or any of the provisions of these Regulations, if he is satisfied that having regard to any special circumstances it is desirable to do so, for such time and on such conditions as the Minister may specify in the notification. Made this 11th. day of Rabiulawal, 1431 · Hijriah corresponding to the 25th. day of February, 2010.\n\nPEHIN ORANG KAYA SETIA PAHLAWAN DATO SERI SETIA DR. A WANG HAJI AHMAD BIN HAJI JUMAT Minister of Culture, Youth and Sports, Brunei Darussalam."}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CHILDREN AND YOUNG PERSONS PLACE OF SAFETY REGULATIONS 2010","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016"] = {"id":"BN-S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":6,"structureMode":"SECTION","title":{"zh":"公司法（修正）命令 2016","en":"COMPANIES ACT AMENDMENT ORDER 2016","orig":"COMPANIES ACT AMENDMENT ORDER 2016","vi":"Sắc lệnh sửa đổi Luật Công ty năm 2016","th":"คำสั่งแก้ไขเพิ่มเติมพระราชบัญญัติบริษัท พ.ศ. 2559","id":"Perintah Perubahan Undang-Undang Perusahaan Tahun 2016","ms":"Perintah Pindaan Akta Syarikat 2016"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016.pdf》（9 页），本次切分 6 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Citation"},"text":{"en":"This Order may be cited as the Companies Act (Amendment) Order, 2016."}},{"id":"BN-S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"Amendment of section 2 of Chapter 39"},"text":{"en":"Section 2 of the Companies Act, in this Order referred to as the Act, is amended, in subsection (I), by inserting the following new definitions in the appropriate alphabetical order - \"\"executive director\" means a director who is concurrently an executive officer and \"non-executive director\" shall be construed accordingly; \"executive officer\" means any person, by whatever name described, who -\n\n(a) is in the direct employment of, or acting for or by arrangement with, the company; and\n\n(b) is concerned with or takes part in the management of the company on a day-to-day basis; \"foreign company\" means any company incorporated outside Brunei Darussalam which has established a place of business in Brunei Darussalam \"limited company\" means a company limited by shares or by guarantee; \"limited liability partnership\" has the meaning given to it by section 5(1) of the Limited Liability Partnerships Order, 2010 (S 11712010); \"related corporation\", in relation to a corporation, means a corporation that is deemed to be related to the first-mentioned corporation by virtue of \"voting share\", in relation to a body corporate, means an issued share in the body corporate, not being -\n\n(a) a share to which, in no circumstances, is there attached a right to\n\n(b) a share to which there is attached a right to vote only in one or more of the following circumstances -\n\n(i) during a period in which a dividend (or part of a dividend) in respect of the share is in arrear;\n\n(ii) on a proposal to reduce the share capital of the body\n\n(iii) on a proposal that affects rights attached to the share;\n\n(iv) on a proposal to wind up the body corporate;\n\n(v) on a proposal for the disposal of the whole of the property, business and undertakings of the body corporate; jvi) during the winding up of the body corporate.\"."}},{"id":"BN-S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"Insertion of new section 63A"},"text":{"en":"The Act is amended by inserting the following new definition immediately \"SUBSTANTIAL SHAREHOLDINGS Substantial shareholdings and substantial shareholders 63A. (1) For the purposes of this Act, a person has a substantial shareholding in a company if - {a) he has an interest or interests in one or more voting shares in\n\n(b) the total votes attached to that share, or those shares, is not 5% of the total votes attached to all the voting shares in the\n\n(2) For the purposes of this Act, a person has a substantial shareholding in a company, being a company the share capital of which is divided into two or more classes of shares, if -\n\n(a) he has an interest or interests in one or more voting shares included in one of those classes; and\n\n(b) the total votes attached to that share, or those shares, is not 5% of the total votes attached to all the voting shares included in that class.\n\n(3) For the purposes of this Act, a person who has a substantial shareholding in a company is a substantial shareholder in that company.\n\n(4) In this section \"voting shares\" exclude treasury shares.\"."}},{"id":"BN-S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016-A4","no":4,"noLabel":{"en":"Section 4."},"heading":{"en":"Insertion of new sections 129A and 129B"},"text":{"en":"The Act is amended by inserting the following two new sections immediately after section 129 - \"When corporations deemed to be related to each other 129A. Where a corporation -\n\n(a) is the holding company of another corporation;\n\n(b) is a subsidiary of another corporation; or\n\n(c) is a subsidiary of the holding company of another corporation, that first-mentioned corporation and that other corporation shall for the purposes of this Act be deemed to be related to each other. Audit committees 129B. (I) Every public company shall have an audit committee.\n\n(2) An audit committee shall be appointed by the directors from among their number (pursuant to a resolution of the board of directors) and shall be composed of 3 or more members of whom a majority shall not be -\n\n(a) executive directors of the company or any related\n\n(b) a spouse, parent, brother, sister, son or adopted son or daughter or adopted daughter of an executive director of the company or of any related corporation; or\n\n(c) any person having a relationship which, in the opinion of the board of directors, would interfere with the exercise of independent judgment in carrying out the functions of an audit committee. 30th. MAY, 2016\n\n(3) The members of an audit committee shall elect a chairman from among their number who is not an executive director or employee of the company or any related corporation.\n\n(4) If a member of an audit committee resigns, dies or for any other reason ceases to be a member with the result that the number of members is 3, the board of directors shall, within 3 months of that event, appoint such number of new members as may be required to make up the minimum number of 3 members.\n\n(5) The functions of an audit committee shall be - (a] to review -\n\n(i) with the auditor, the audit plan;\n\n(ii) with the auditor, his evaluation of the system of internal accounting controls;\n\n(iii) with the auditor, his audit report;\n\n(iv) the assistance given by the officers of the company to\n\n(v) the scope and results of the internal audit procedures; and\n\n(vi) the balance sheets of the company and of the . parent company, submitted to it by the company or the parent company, and thereafter to submit them to the directors of the company or parent company; and (b] to nominate a or as notwithstanding anything contained in the memorandum and articles of association of the company or under section 131, together with such other functions as may be agreed to by the audit committee and the board of directors.\n\n(6) The auditor has the right to appear and be heard at any meeting of the audit committee and shall appear before the audit committee when required to do so by the audit committee.\n\n(7) On the request of the auditor, the chairman of the audit committee shall convene a meeting of the audit committee to consider any matter the auditor believes should be brought to the attention of the directors or shareholders.\n\n(8) Each audit committee may regulate its own procedure and in particular the calling of meetings, the notice to be given of such meetings, the voting and proceedings thereat, the keeping of minutes and the custody, production and inspection of such minutes.\n\n(9) Any reference in this section to a director who is not an executive director of a company is a reference to a director who is not an employee of, and does not hold any other office of profit in, the company or in any related corporation of that company in conjunction with his office of director and his membership of any audit committee, and any reference to an executive director shall be read accordingly.\n\n(10) If any person being a director of a company -\n\n(a) fails to comply with any provision of this section;\n\n(b) fails to take all reasonable steps to secure compliance by the company with any such provision; or\n\n(c) has by his own wilful act been the cause of any default by the company of any such provision, he is guilty of an offence and liable on conviction to a fine not exceeding $5,000 or imprisonment for a term not exceeding 2 years: Provided that a person shall not be sentenced to imprisonment for an offence under this section unless, in the opinion of the Court dealing with the case, the offence was committed wilfully.\"."}},{"id":"BN-S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016-A5","no":5,"noLabel":{"en":"Section 5."},"heading":{"en":"Insertion of new section 153A"},"text":{"en":"The Act is amended by inserting the following new section immediately after \"Personal remedies in cases of oppression or injustice 153A. (3.) Any member or holder of a debenture of a company may apply to the Court for an order under this section on the ground -\n\n(a) that the affairs of the company are being conducted or the powers of the directors are being exercised in a manner oppressive to one or more of the members or holders of debentures including himself or in disregard of his or their interests as members, shareholders or holders of debentures of the company; or\n\n(b) that some act of the company has been done or is threatened or that some resolution of the members, holders of debentures or any class of them has been passed or is proposed which unfairly discriminates against or is otherwise prejudicial to one or more of the members or holders of debentures (including himself).\n\n(2) If on such application the Court is of the opinion that either of such grounds is established, the Court may, with a view to bringing to an end or remedying the matters complained of, make such order as it thinks fit and, without prejudice to the generality of the foregoing, the order may -\n\n(a) direct or prohibit any act or cancel or vary any transaction\n\n(b) regulate the conduct of the affairs of the company in future;\n\n(c) authorise civil proceedings to be brought in the name of or on behalf of the company by such person or persons and on such terms as the Court may direct;\n\n(d) provide for the purchase of the shares or debentures of the company by other members or holders of debentures of the company or-by the company itself;\n\n(e) in the case of a purchase of shares by the company, provide for a reduction accordingly of the capital of the company; or\n\n(f) provide that the company be wound up.\n\n(3) Where an order that the company be wound up is made pursuant to subsection (2)(fl, the provisions of the Insolvency Order, 2016 (S 112016) relating to the winding up of a company shall, with such . adaptations as are necessary, apply as if the order had been made on an application duly made to the Court by the company.\n\n(4) Where an order under this section makes any alteration in or addition to any memorandum or articles of notwithstanding anything in any other provisions of this Act, but subject to the provisions of the order, the company concerned shall not have power, without the leave of the Court, to make any further alteration in or addition to the memorandum or articles inconsistent with the provisions of the order; but subject to the foregoing provisions of this subsection, the alterations or additions made by the order shall be of the same effect as if duly made by resolution of the company.\n\n(5) A copy of any order made under this section shall be lodged by the applicant with the Registrar within 14 days after the making of the\n\n(6) Any person who fails to comply with subsection (5) is guilty of an offence and liable on conviction to a fine not exceeding $1,000 and also to a default fine.\n\n(7) This section shall apply to a person who is not a member of a company but to whom shares in the company have been transmitted by operation of law as it applies to members of a company; and references to a member or members shall be construed accordingly.\". Insertion of new section 324A"}},{"id":"BN-S-33-2016-COMPANIES-ACT-AMENDMENT-ORDER-2016-A6","no":6,"noLabel":{"en":"Section 6."},"heading":{"en":"CONSTITUTION OF BRUNEI DARUSSALAM"},"text":{"en":"The Act is amended by inserting the following new section immediately after 324A. (1) The Minister may, with the approval of His Majesty the Sultan and Yang Di-Pertuan, make such rules as may be necessary or expedient for carrying out the purposes and provisions of this Act and for prescribing anything that may be required or authorised to be by this Act.\n\n(2) Without prejudice to the generality of subsection (I), rules may be made for or with respect to the corporate governance of companies incorporated in Brunei Darussalam or their related corporations.\n\n(3) Rules made under this section may relate to all or any class, category or description of persons or companies, and may make different provisions for different classes, categories or descriptions of persons or companies or to a particular person or company or of general or specifically limited application.\n\n(4) Except as otherwise expressly provided in this Act, rules made under this section may provide that any contravention thereof shall be an offence punishable -\n\n(a) in the case of an individual, with a fine not exceeding $12,500, imprisonment for a term not exceeding 12 months or both and, in the case of a continuing offence, with a further fine not exceeding $1,250 for every day or part thereof during which the offence continues after conviction; or\n\n(b) in any other case, with a fine not exceeding $25,000 and, in the case of a continuing offence, with a further fine not exceeding $2,500 for every day or part thereof during which the offence continues after conviction.\". 30th. MAY, 2016 Made this 23rd. day of Sya'ban, 1437 Hijriah corresponding to the 30th. day of May, 2016 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM"}}],"pack":"bn-p28","titleTranslation":{"engine":"manual-llm","reviewed":false,"source":"COMPANIES ACT AMENDMENT ORDER 2016","note":"人工逐条翻译（模型产出，未经人工复核）；公司名、地名、机构名保留原文。"}};
