  FT["BN-S-33-2024-E-EMPLOYMENT-AMENDMENT-ORDER-2024-1"] = {"id":"BN-S-33-2024-E-EMPLOYMENT-AMENDMENT-ORDER-2024-1","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"就业修正命令 2024(1)","en":"Employment Amendment Order 2024(1)","orig":"Employment Amendment Order 2024(1)","vi":"Sắc lệnh sửa đổi Sắc lệnh Việc làm số 1 năm 2024","th":"คำสั่งแก้ไขเพิ่มเติมคำสั่งการจ้างงาน ฉบับที่ 1 พ.ศ. 2567","id":"Perintah Perubahan Perintah Ketenagakerjaan Nomor 1 Tahun 2024","ms":"Perintah Pindaan Perintah Pekerjaan Bilangan 1 2024"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《s-33-2024-e-employment-amendment-order-2024(1).pdf》（3 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"s-33-2024-e-employment-amendment-order-2024(1).pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-33-2024-E-EMPLOYMENT-AMENDMENT-ORDER-2024-1-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Order may be cited as the Employment (Amendment) Order, 2024. of section 113A of S 37/2009"}},{"id":"BN-S-33-2024-E-EMPLOYMENT-AMENDMENT-ORDER-2024-1-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"of section 113A of S 37/2009 3rd. JULY, 2024 made under Article 83(3)) (AMENDMENT) ORDER, 2024 In exercise of the power conferred by Article 83(3) of the Constitution of Brunei Darussalam, His Majesty the Sultan and Yang Di-Pertuan hereby makes the following Order -"}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"Employment Amendment Order 2024(1)","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-34-1960-APPOINTMENT-OF-DISTRICT-OFFICERS-TO-BE-ASSI-DE70E9"] = {"id":"BN-S-34-1960-APPOINTMENT-OF-DISTRICT-OFFICERS-TO-BE-ASSI-DE70E9","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"任命县官员担任州人口普查助理监督","en":"Appointment of District Officers to Be Assistant Superintendents of Census of the State","orig":"Appointment of District Officers to Be Assistant Superintendents of Census of the State","vi":"Sắc lệnh Bổ nhiệm quan chức huyện làm Phó giám đốc điều tra dân số bang","th":"คำสั่งการแต่งตั้งเจ้าหน้าที่อำเภอเป็นผู้ช่วยผู้ควบคุมสำมะโนแห่งรัฐ","id":"Perintah Pengangkatan Pejabat Distrik sebagai Asisten Pengawas Sensus Negara Bagian","ms":"Perintah Pelantikan Pegawai Daerah sebagai Penolong Penguasa Banci Negeri"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《s-34-1960-appointment-of-district-officers-to-be-assistant-superintendents-of-census-of-the-state.pdf》（1 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"s-34-1960-appointment-of-district-officers-to-be-assistant-superintendents-of-census-of-the-state.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-34-1960-APPOINTMENT-OF-DISTRICT-OFFICERS-TO-BE-ASSI-DE70E9-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"[ e C j j55 J; No. S 34. THE CENSUS ENACTMENT (Cap. 78). In exercise of powers conferred upon him by subsection (1) of Section 4 of the Census Enact­ ment (Cap. 78), His Highness the Sultan has appointed the following District Officers to be Assist­ ant Superintendents of Census for the State :- District Officer, Brunei & Muara; District Officer, Belait; District Officer, Tutong; District Officer, Temburong. By Command.\n\nWAN AHMAD State Secretary, Brunei. [Ref: SUK.8j60J."}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"Appointment of District Officers to Be Assistant Superintendents of Census of the State","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-34-1978-DECLARATION-MUNICIPAL-BOARD-AREA-AMENDMENT-2FF15D"] = {"id":"BN-S-34-1978-DECLARATION-MUNICIPAL-BOARD-AREA-AMENDMENT-2FF15D","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"马来奕市政局区域宣告（修正）1974","en":"DECLARATION MUNICIPAL BOARD AREA AMENDMENT KUALA BELAIT 1974","orig":"DECLARATION MUNICIPAL BOARD AREA AMENDMENT KUALA BELAIT 1974","vi":"Sắc lệnh Tuyên bố khu vực Hội đồng Thị chính Kuala Belait (sửa đổi) năm 1974","th":"คำสั่งการประกาศเขตคณะกรรมการเทศบาลกัวลาบือไลต์ (แก้ไข) พ.ศ. 2517","id":"Perintah Pernyataan Wilayah Dewan Kotamadya Kuala Belait (Perubahan) Tahun 1974","ms":"Perintah Perisytiharan Kawasan Lembaga Perbandaran Kuala Belait (Pindaan) 1974"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-34-1978-DECLARATION-MUNICIPAL-BOARD-AREA-AMENDMENT-KUALA-BELAIT-1974.pdf》（2 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-34-1978-DECLARATION-MUNICIPAL-BOARD-AREA-AMENDMENT-KUALA-BELAIT-1974.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-34-1978-DECLARATION-MUNICIPAL-BOARD-AREA-AMENDMENT-2FF15D-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Declaration may be cited as the Declaration (Municipal Board Area) (Amend­ ment) Kuala Belait 1974 and shall be read as one with the Declaration (Kuala Belait and Seria Municipal Areas) 1959 (hereinafter referred to as \"the Principal Declaration\")."}},{"id":"BN-S-34-1978-DECLARATION-MUNICIPAL-BOARD-AREA-AMENDMENT-2FF15D-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Principal Declaration is hereby amended by deleting the First Schedule to the Declaration and substituting therefor the following: - \"Kuala Belait Municipal Board Area The Area on the East side of the Belait River bounded as follows:- Commencing at the point on the estuary of the Belait River 360 feet to the west of right bank of the River, thence running northwards facing the China Sea for a distance of 1,200 feet, thence fol­ lowing a line approximately 280 feet from a row of trees along the bank facing the China Sea eastwards to a point 210 feet beyond the eastern boundary of the Is­ tana Manggalela, thence running inlands in a southerly direction for a distance of 1,240 feet, thence eastwards along the southern part of Seria/Kuala Belait Road and the Roundabout at Mile 4 in a southerly direction along the southern part of the Kuala Belait/Seria main road to the point on the southern boundary of the area occupied by the Brunei Shell Petroleum Company Limited for its sewerage disposal, thence following the boundary of the said sewerage area to the point where it turns in a south-west di­ rection . and thence following the boundary to the west of the occupied area in a south-west direction to the point at the Belait River 180 feet from the west bank, thence following the line in the middle of the Belait River to the point of commencement at the estuary of the Belait River 360 feet from the right bank\". Ref: SUKl576/53 Date: 31st January, 1978."}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"DECLARATION MUNICIPAL BOARD AREA AMENDMENT KUALA BELAIT 1974","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0"] = {"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":13,"structureMode":"SECTION","title":{"zh":"儿童与青少年探访委员会条例 2010","en":"CHILDREN AND YOUNG PERSONS BOARDS OF VISITORS REGULATIONS 2010","orig":"CHILDREN AND YOUNG PERSONS BOARDS OF VISITORS REGULATIONS 2010","vi":"Quy định Ban thăm viếng về trẻ em và người chưa thành niên năm 2010","th":"ข้อบังคับคณะกรรมการเยี่ยมเด็กและเยาวชน พ.ศ. 2553","id":"Peraturan Dewan Pengunjung Anak dan Remaja Tahun 2010","ms":"Peraturan Lembaga Pelawat Kanak-Kanak dan Orang Muda 2010"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITORS-REGULATIONS-2010.pdf》（6 页），本次切分 13 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITORS-REGULATIONS-2010.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Regulations may be cited as the Children and Young Persons (Boards of Visitors) Regulations, 2010 and shall commence on the same date as the Children and Young Persons Order, 2006. Interpretation."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In these Regulations, unless the context otherwise requires\"Board\" means a board appointed under section 75(1) of the Order; \"resident\" means any child or young person for the time being detained under the Order in an approved school, approved home, remand home, place of detention or place of safety. Constitution of Board."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"(1) Every Board shall consist of\n\n(a) a Chairman;\n\n(b) a Vice-Chairman; and (cl such number of other members as the Minister may appoint.\n\n(2) At least one of the members of every Board shall be a nominee of the Director.\n\n(3) The Minister may at any time revoke the appointment of any member of a Board. Chairman."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(1) The Minister shall appoint one of the members to be the Chairman.\n\n(2) The Chairman shall preside at all meetings. Vice-Chairman."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(1) The Vice-Chairman shall be elected by the Board from amongst its members.\n\n(2) In the absence of the Chairman, the Vice-Chairman shall preside at all meetings of the Board and may exercise all the powers and functions of the Chairman. Secretary."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Director shall appoint a secretary to each Board, except that the person appointed shall not\n\n(a) be a member of the Board; or {b) vote at any proceedings of the Board. Term of office of members."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(1) Each member shall hold office for a period of not more than 2 years from the date of his appointment and shall be eligible for re-appointment on completion of that period, unless {a) he resigns during his term of office; or {b) his appointment is revoked by the Minister under regulation 3(3).\n\n(2) Any member may resign at any time by giving notice in writing to the Minister.\n\n(3) If a member dies, resigns, has his appointment revoked by the Minister under regulation 3(3) or otherwise vacates his office before the expiry of the term for which he has been appointed, the Minister may appoint any other person to fill the vacancy for so long as the member in whose place that person is appointed would have held office.\n\n(4) A Board shall not be precluded.from holding a meeting or acting in any matter merely by reason of any vacancy in its membership. Meetings."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"(1) A Board shall meet as often as may be required, but in any case, it shall meet at least once in every 2 months.\n\n(2) The quorum at every meeting of a Board shall be two-thirds of the members.\n\n(3) No business of a Board shall be transacted at any meeting unless a quorum is present.\n\n(4) Every question coming before or arising at any meeting of a Board shall be decided by a majority of members present and voting thereon at the meeting and, in the case of an equality of votes, the Chairman or, in his absence, the ViceChairman shall have a casting vote. Attendance of manager and staff of approved school, approved home etc. at meeting of Board."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A9","no":9,"noLabel":{"en":"Section 9."},"heading":{"en":"Attendance of manager and staff of approved school, approved home etc. at"},"text":{"en":"The manager and the members of the staff of an approved school, approved home, remand home, place of detention or place of safety shall attend any meeting held by the Board appointed in respect of the approved school, approved home, remand home, place of detention or place of safety if required by the Board to do so. Duties of members of Board."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"(1) Not less than 2 members of each Board shall visit together at least once in 2 months each approved school, approved home, remand home, place of detention or place of safety in respect of which the Board is appointed.\n\n(2) Any member may, whenever he thinks fit, enter the approved school, approved home, remand home, place of detention or place of safety in respect of which the Board is appointed and examine the conditions thereof in order to -\n\n(a) ascertain, so far as is possible, whether the provisions of the Order and any regulations made thereunder governing the approved school, approved home, remand home, place of detention or place of safety are being adhered to, and shall call the attention of the manager of the approved school, approved home, remand home, place of detention or place of safety to any irregularity as may be observed in the management thereof or the treatment of the residents therein; and {b) hear any complaint which any resident may wish to make. {3) Any member may record any observation as he thinks fit in the book kept for that purpose by the manager of the approved school, approved home, remand home, place of detention or place of safety in respect of which the Board is appointed.\n\n(4) Every Board shall send to the Director any comments or recommendations it may make regarding an approved school, approved home, remand home, place of detention or place of safety in respect of which it is appointed. (51 Upon receipt of any comments or recommendations from any Board pursuant to sub-regulation (4), the Director shall take such action as may be necessary, and report to the Board as soon as possible any action that has been taken by him. Defects in administration."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A Board shall bring to the notice of the Director any defect in the administration of the approved school, approved home, remand home, place of detention or place of safety, any neglect with regard to the welfare of any child or any breach or non-observance of these Regulations and of any other regulations made under the Order. Activities."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"( 1) A Board may advise such activities as may be suitable for the children in an approved school, approved home, remand home, place of detention or place of safety according to their age and development, and may recommend and assist the Director ~ {a) in the placing of the children with suitable foster-families; or {b) in obtaining suitable training or employment for the children.\n\n(2) For that purpose, the members shall avail themselves where necessary of any assistance that can be obtained, whether from public organisations or private individuals. Manager of approved school, approved home, etc. to assist members of Board."}},{"id":"BN-S-34-2010-CHILDREN-AND-YOUNG-PERSONS-BOARDS-OF-VISITO-5320C0-A13","no":13,"noLabel":{"en":"Section 13."},"heading":{"en":"Manager of approved school, approved home, etc. to assist members of"},"text":{"en":"Every manager shall use his best endeavours to assist any member of the Board appointed in respect of an approved school, approved home, remand home, place of detention or place of safety in the exercise of his powers and the discharge of his functions under the Order or these Regulations. Made this 11th. day of Rabiulawal, 1431 Hijriah corresponding to the 25th. day of February, 2010.\n\nPEHIN ORANG KAYA SETIA PAHLAWAN DATO SERI SETIA DR. A WANG HAJI AHMAD BIN HAJI JUMAT Minister of Culture, Youth and Sports, Brunei Darussalam."}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CHILDREN AND YOUNG PERSONS BOARDS OF VISITORS REGULATIONS 2010","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497"] = {"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":8,"structureMode":"SECTION","title":{"zh":"公司（公众公司治理）（修正）规则 2016","en":"COMPANIES CORPORATE GOVERNANCE PUBLIC COMPANIES AMENDMENT RULES 2016","orig":"COMPANIES CORPORATE GOVERNANCE PUBLIC COMPANIES AMENDMENT RULES 2016","vi":"Quy tắc sửa đổi Quy tắc Công ty: quản trị công ty đối với công ty đại chúng năm 2016","th":"ข้อกำหนดแก้ไขเพิ่มเติมข้อกำหนดบริษัท: การกำกับดูแลกิจการของบริษัทมหาชน พ.ศ. 2559","id":"Peraturan Perubahan Peraturan Perseroan: Tata Kelola Perusahaan Terbuka Tahun 2016","ms":"Kaedah Pindaan Kaedah Syarikat: Tadbir Urus Korporat Syarikat Awam 2016"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-34_2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPANIES-AMENDMENT-RULES-2016.pdf》（6 页），本次切分 8 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-34_2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPANIES-AMENDMENT-RULES-2016.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Citation and commencement"},"text":{"en":"These Rules may be cited as the Companies (Corporate Governance) (Public Companies) Rules, 2016 and shall commence on the same date as the Companies Act (Amendment) Order, 2016."}},{"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"Interpretation"},"text":{"en":"In these Rules, unless the context otherwise requires - \"immediate family\", in relation to an individual, means the spouse, child, adopted child, stepchild, parent, step-parent, brother, stepbrother, sister or \"independent director\" means a director who -\n\n(a) is independent from any management and business relationship with the public company or of any related corporation; and\n\n(b) is independent from any substantial shareholder of the public , company or of any related corporation; \"substantial shareholder\" has the meaning given to it by section 63A."}},{"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"Application"},"text":{"en":"These Rules apply to every public company incorporated and registered in Brunei Darussalam, irrespective of the place or places where the business of such company may be carried on."}},{"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497-A4","no":4,"noLabel":{"en":"Section 4."},"heading":{"en":"Independence from management and business relationships"},"text":{"en":"(1) In these Rules, a director shall be considered to be independent from management and business relationships with a public company if -\n\n(a) the director has no management relationship with the company or any of its subsidiaries; and\n\n(b) the director has no business relationship with the company or any of its subsidiaries, or with any officer of the company, that could interfere, or be reasonably regarded as interfering, with the exercise of the independent business judgment of the director with regard to the interests of\n\n(2) Without prejudice to subrule (l)(a), a director shall not be considered to be independent from management relationships with a public company or any of its subsidiaries if -\n\n(a) he is employed by the company or any of its subsidiaries, or has been so employed at any time during the current financial year or any of the 3 financial years of the company or any of its subsidiaries;\n\n(b) any member of his immediate family -\n\n(i) is employed by the company or any of its subsidiaries as an executive officer whose compensation .is. determined by the company or any of its subsidiaries; or\n\n(ii) has been so employed at any time during the current financial year or any of the preceding 3 financial years of the company or any of its subsidiaries; or\n\n(c) he is accustomed or under an obligation, whether formal or informal, to act in accordance with the directions, instructions or wishes of . the management of the company or any of its subsidiaries.\n\n(3) Without prejudice to subrule (l)(b), a director shall not be considered to be independent from business relationships with a public company or any of its\n\n(a) he is a director, a substantial shareholder or an executive officer of any corporation, or a partner of a firm or a limited liability partnership or a sole proprietor, where such corporation, firm, limited liability partnership or sole proprietor carries on business for purposes of profit to which the company or any of its subsidiaries has made, or from which the company or any of its subsidiaries has received, payments in the current or immediately preceding financial year; or\n\n(b) he is receiving or has received any compensation from the company or from any of the subsidiaries of the company, other than compensation received for his services as a director or as an employee, at any time during the current or immediately preceding financial year of the 30th. MAY, 2016 from substantial shareholder"}},{"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497-A5","no":5,"noLabel":{"en":"Section 5."},"heading":{"en":"Independence from substantial shareholder"},"text":{"en":"(1) In these Rules, a director of a public company shall be considered to be independent from a substantial shareholder of the company or of any related corporation if he is not that substantial shareholder and is not connected to that substantial shareholder.\n\n(2) Notwithstanding subrule (I), a director of a public company which is the immediate subsidiary of another public company (referred to in this subrule as the parent company) shall, if he is not a substantial shareholder of the public company or the parent company and is not connected to -\n\n(a) a substantial shareholder of the public company (other than the parent company); or\n\n(b) a substantial shareholder of the parent company, be treated as if he were independent from the substantial shareholder of the public company for the purposes of rules 6(1) and 7.\n\n(3) For the purposes of subrule (I), a person is connected to a substantial shareholder if he is -\n\n(a) in the case where the substantial shareholder is an individual -\n\n(i) a member of the immediate family of the substantial\n\n(ii) . employed by the substantial shareholder;\n\n(iii) employed by an affiliate of the substantial shareholder;\n\n(iv) an executive director of an affiliate of the substantial\n\n(v) a non-executive director of an affiliate of the substantial\n\n(vi) a partner of a firm or a limited liability partnership of which the substantial shareholder is also a partner; or\n\n(vii) accustomed or under an obligation, whether formal or informal, to act in accordance with the directions, instructions or wishes of the substantial shareholder; or\n\n(b) in the case where the substantial shareholder is a corporation -\n\n(i) employed by the substantial shareholder;\n\n(ii) employed by an affiliate of the substantial shareholder;\n\n(iii) a director of the substantial shareholder;\n\n(iv) an executive director of an affiliate of the substantial\n\n(v) a non-executive director of an affiliate of the substantial\n\n(vi) a partner of a firm or a limited liability partnership of which the substantial shareholder is also a partner; or\n\n(vii) accustomed or under an obligation, whether formal or informal, to act in accordance with the directions, instructions or wishes of the substantial shareholder."}},{"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497-A6","no":6,"noLabel":{"en":"Section 6."},"heading":{"en":"Board of directors"},"text":{"en":"(1) A public company shall have a board of directors comprising at least a majority of directors who are independent directors.\n\n(2) Any public company which contravenes subrule (1) is guilty of an offence and liable on conviction to a fine not exceeding $25,000 and, in the case of a continuing offence, to a further fine not exceeding $2,500 for every day or . part thereof during which the offence continues after conviction."}},{"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497-A7","no":7,"noLabel":{"en":"Section 7."},"heading":{"en":"Executive Committee"},"text":{"en":"Where the board of directors of a public company has delegated any of its powers for the oversight of the company to an executive committee or any other committee by whatever name described (referred to in this rule as an Executive Committee), consisting of such directors as the board of directors thinks fit, rule 6 shall apply, with the necessary modifications, to the company in respect of the Executive Committee as if the Executive Committee were a board of directors."}},{"id":"BN-S-34-2016-COMPANIES-CORPORATE-GOVERNANCE-PUBLIC-COMPA-D5D497-A8","no":8,"noLabel":{"en":"Section 8."},"heading":{"en":"In exercise of the power conferred by section 324A[2) of the Companies Act,"},"text":{"en":"(1) The Minister may, with the approval of His Majesty the Sultan and Yang Di-Pertuan, on the application of any public company, by notice in writing exempt the public company from all or any of the provisions of these Rules, subject to such conditions as the Minister may determine, if the Minister considers it appropriate to do so in the circumstances of the case.\n\n(2) Any public company which fails to comply with any condition imposed by the Minister under subrule (1) is guilty of an offence and liable on conviction to a fine not exceeding $25,000.\n\n(3) An exemption granted under subrule (1) may be withdrawn by the Minister at any time. Made this 23rd. day of Sya'ban, 1437 Hijriah corresponding to the 30th. day of May, 2016 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM Minister of Finance, Brunei Darussalam."}}],"pack":"bn-p28","titleTranslation":{"engine":"manual-llm","reviewed":false,"source":"COMPANIES CORPORATE GOVERNANCE PUBLIC COMPANIES AMENDMENT RULES 2016","note":"人工逐条翻译（模型产出，未经人工复核）；公司名、地名、机构名保留原文。"}};
  FT["BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9"] = {"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":26,"structureMode":"SECTION","title":{"zh":"斯里巴加湾市市政局常设命令附例 2018","en":"BANDAR SERI BEGAWAN MUNICIPAL BOARD STANDING ORDERS BY LAWS 2018","orig":"BANDAR SERI BEGAWAN MUNICIPAL BOARD STANDING ORDERS BY LAWS 2018","vi":"Luật Quy chế của Ủy ban Đô thị Bandar Seri Begawan năm 2018","th":"พระราชบัญญัติข้อบังคับของคณะกรรมการเทศบาล Bandar Seri Begawan พ.ศ. 2561","id":"Undang-Undang Tata Tertib Dewan Kotamadya Bandar Seri Begawan Tahun 2018","ms":"Akta Perintah Tetap Lembaga Perbandaran Bandar Seri Begawan 2018"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2018.pdf》（7 页），本次切分 26 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDING-ORDERS-BY-LAWS-2018.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"These By-Laws may be cited as the Bandar Seri Begawan Municipal Board"},"text":{"en":"These By-Laws may be cited as the Bandar Seri Begawan Municipal Board (Standing Orders] By-Laws, 2018."}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"\"Board\" means the Bandar Seri Begawan Municipal Board;"},"text":{"en":"In these By-Laws, unless the context requires otherwise - \"meeting\" means any meeting of the Board; \"member\" means member of the Board; \"secretary\" means the person appointed by the Chairman to be the secretary; \"working day\" means any day other than a Friday, Sunday or public holiday."}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"The procedure prescribed under these By-Laws shall be observed for the"},"text":{"en":"The procedure prescribed under these By-Laws shall be observed for the order and conduct of business of the Board and any of its committee. Frequency, time and place of meetings"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A4","no":4,"noLabel":{"en":"Section 4."},"heading":{"en":"meet at least six times a year at such time and place as may be notified by the"},"text":{"en":"The Board shall convene as often as may be required, but in any case, it shall Notice of meetings"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A5","no":5,"noLabel":{"en":"Section 5."},"heading":{"en":"7 days prior to the date of the meeting:"},"text":{"en":"The Chairman shall cause notice of the meeting to be given to members not Provided that accidental omission to give such notice shall not invalidate any proceedings at any such meetings: Provided further that in a case of urgency, the Chairman may direct that notice to be disposed with. Doa"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All meetings of the Board shall open with a doa.\n\nOF PROCEEDINGS"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(1) At a meeting, two-thirds of the members shall form a quorum.\n\n(2) No business of the Board shall be transacted at any meeting thereof unless a quorum is present. Chairman to preside"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"(1) As soon as a quorum is present, the Chairman shall take the chair and call the members to order. ( 2 ) The Chairman shall preside at any meeting of the Board and shall have the general control of all deliberations and proceedings of the meeting.\n\n(3) If the Chairman is absent or for any other reason is unable to discharge his functions, the members present may elect one of them to preside at the Duties of secretary"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A9","no":9,"noLabel":{"en":"Section 9."},"heading":{"en":"The secretary shall -"},"text":{"en":"The secretary shall -\n\n(a) under the direction of the Chairman, have charge of all correspondence and documents of the Board; and\n\n(b) in all other respects, carry out such duties as may be imposed upon him by these By-Laws or assigned to him by direction of the Chairman. 26th. JULY, 2018"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"(1) The secretary shall keep minutes of all meetings.\n\n(2) As soon as possible after every meeting, a copy of the draft minutes shall be sent to members. If on confirmation such draft minutes are amended, the Chairman shall forthwith be informed of the amendments made. Adjournment of meeting"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A11","no":11,"noLabel":{"en":"Section 11."},"heading":{"en":"quorum"},"text":{"en":"The Chairman of a meeting may, with consent of the members, adjourn the"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A12","no":12,"noLabel":{"en":"Section 12."},"heading":{"en":"for the meeting, the secretary shall take down the names of the members then"},"text":{"en":"If there is no quorum present within one-half hour after the time appointed present and the meeting shall be adjourned to such day as the Chairman may appoint, being not less than 7 nor more than 21 days after the day first appointed. Chairman to preserve order and decorum"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A13","no":13,"noLabel":{"en":"Section 13."},"heading":{"en":"The Chairman shall preserve order and decorum and shall decide all question"},"text":{"en":"The Chairman shall preserve order and decorum and shall decide all question of order subject to an appeal by any member. of precedence in speaking"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A14","no":14,"noLabel":{"en":"Section 14."},"heading":{"en":"When two or more members arise to speak at the same time, the Chairman"},"text":{"en":"When two or more members arise to speak at the same time, the Chairman shall name the member who, in his opinion, has right of precedence. Member to address Chairman while speaking"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A15","no":15,"noLabel":{"en":"Section 15."},"heading":{"en":"Offensive word or epithet not to be used"},"text":{"en":"Every member while speaking shall respectfully address the Chairman."}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A16","no":16,"noLabel":{"en":"Section 16."},"heading":{"en":"No member shall -"},"text":{"en":"No member shall -\n\n(a) apply any offensive word or epithet to the Board or any member; or\n\n(b) speak outside the question under debate. Member speaking not to be interrupted except on point of order"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A17","no":17,"noLabel":{"en":"Section 17."},"heading":{"en":"hold any private discourse, or make any noise or disturbance, or interrupt a"},"text":{"en":"When a member is speaking or a question is being put, no member shall speaker except to raise a point of order. Member to speak once only on same question"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A18","no":18,"noLabel":{"en":"Section 18."},"heading":{"en":"leave of the Chairman, except a member who has made a substantive motion who"},"text":{"en":"No member shall speak more than once on the same question without the shall be allowed a reply. No member shall speak on the same question, or in reply, for longer than 5 minutes. Questions or enquiries relating to by-law etc."}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A19","no":19,"noLabel":{"en":"Section 19."},"heading":{"en":"member relating to any by-law, motion or other matter connected with the"},"text":{"en":"Questions or enquiries may be put to the Chairman or through him to any business of the Board, but no argument or opinion is to be offered or facts to be stated. Every member present to vote"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A20","no":20,"noLabel":{"en":"Section 20."},"heading":{"en":"put, shall have the right to vote thereon, unless he is disqualified by interest, in"},"text":{"en":"(1) Every member, who shall be present in the meeting when a motion is which case he shall not vote.\n\n(2) Any member who is directly or indirectly interested with respect to any motion shall disclose the nature of his interest after the relevant facts of the motion has come to his knowledge.\n\n(3) A disclosure under sub-by-law (2) shall be recorded in the minutes of meeting and after the disclosure, the member shall be disqualified from taking part in any deliberation or decision of the Board with respect to that motion."}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A21","no":21,"noLabel":{"en":"Section 21."},"heading":{"en":"the members present and, in the case of an equality of votes, the Chairman or, in"},"text":{"en":"All motions arising at any meeting shall be decided by a majority of votes of his absence, the member acting as Chairman, shall have a casting vote. DAY General Orders of the day"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A22","no":22,"noLabel":{"en":"Section 22."},"heading":{"en":"of the day\" as follows -"},"text":{"en":"The secretary shall notify the members in the meetings \"The General Orders\n\n(a) confirmation of the agenda;\n\n(b) presentation and consideration of reports;\n\n(c) motions;\n\n(d) the giving of notices of motion;\n\n(e) confirmation of the minutes of meeting; (fl any other businesses arising from the meeting."}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A23","no":23,"noLabel":{"en":"Section 23."},"heading":{"en":"Notice of all motions introducing any new matter shall be given within 5"},"text":{"en":"Notice of all motions introducing any new matter shall be given within 5 working days, and all motions shall be placed in \"The General Orders of the day\". Motion in writing and seconded"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A24","no":24,"noLabel":{"en":"Section 24."},"heading":{"en":"Every motion shall be in writing and read by the Chairman, but shall be"},"text":{"en":"Every motion shall be in writing and read by the Chairman, but shall be seconded before being put or debated."}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"All motions shall be recorded by the secretary together with the voting\n\nS 9711963"}},{"id":"BN-S-34-2018-BANDAR-SERI-BEGAWAN-MUNICIPAL-BOARD-STANDIN-9562F9-A26","no":26,"noLabel":{"en":"Section 26."},"heading":{"en":"The Brunei Municipal Board (Standing Orders) By-Laws, 1963 is hereby"},"text":{"en":"The Brunei Municipal Board (Standing Orders) By-Laws, 1963 is hereby repealed. Made this 3rd. day of Ramadhan, 1439 Hijriah corresponding to the 19th. day of May, 2018.\n\nAWANG HAJI ALI BIN MATYASSIN Bandar Seri Begawan Municipal Board. Confirmed this 26th. day of Syawal, 1439 Hijriah corresponding to the 10th. day of July, 2018.\n\nPEHIN ORANG KAYA SERI KERNA DATO SERI SETIA (DR.) HAJI AWANG ABU BAKAR BIN HAJI APONG Minister of Home Affairs, Brunei Darussalam."}}],"pack":"bn-p28","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"BANDAR SERI BEGAWAN MUNICIPAL BOARD STANDING ORDERS BY LAWS 2018","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
